import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Mail, Lock, Eye, EyeOff, AlertCircle } from 'lucide-react';
import AuthLayout from './AuthLayout';

const Login = ({ onLogin }) => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    email: '',
    password: '',
    rememberMe: false,
  });

  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [loginError, setLoginError] = useState('');

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));

    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
    if (loginError) setLoginError('');
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.email.trim()) {
      newErrors.email = "L'email est requis";
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = "L'email est invalide";
    }

    if (!formData.password) {
      newErrors.password = 'Le mot de passe est requis';
    }

    return newErrors;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const validationErrors = validateForm();
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }

    setIsSubmitting(true);
    setLoginError('');

    // Simulation d'API
    setTimeout(() => {
      if (formData.email === 'enzo@gmail.com' && formData.password === '41329758@#Enzo') {
        console.log('Connexion réussie:', formData);

        // Sauvegarder les données
        localStorage.setItem('isAuthenticated', 'true');
        localStorage.setItem('userEmail', formData.email);
        if (formData.rememberMe) {
          localStorage.setItem('rememberMe', 'true');
        }

        // Appeler le callback de connexion
        onLogin();

        // Rediriger
        navigate('/dashboard');
      } else {
        setLoginError('Email ou mot de passe incorrect');
      }
      setIsSubmitting(false);
    }, 1000);
  };

  return (
    <AuthLayout
      title="Content de vous revoir"
      subtitle="Connectez-vous à votre compte pour continuer."
      type="login"
    >
      <form onSubmit={handleSubmit} className="space-y-6">
        {loginError && (
          <div className="p-4 rounded-lg bg-red-50 dark:bg-red-900/30 border border-red-200 dark:border-red-800">
            <div className="flex items-center">
              <AlertCircle className="text-red-600 dark:text-red-400 mr-2" size={20} />
              <span className="text-red-700 dark:text-red-300 font-medium">
                {loginError}
              </span>
            </div>
          </div>
        )}

        {/* Demo credentials */}
        <div className="p-4 rounded-lg bg-primary-50 dark:bg-primary-900/20 border border-primary-200 dark:border-primary-800">
          <h4 className="font-semibold text-primary-800 dark:text-primary-300 mb-2">
            🔐 Identifiants de démonstration
          </h4>
          <div className="text-sm text-primary-700 dark:text-primary-400 space-y-1">
            <p>Email: <span className="font-mono">enzo@gmail.com</span></p>
            <p>Mot de passe: <span className="font-mono">41329758@#Enzo</span></p>
          </div>
        </div>

        {/* Email Field */}
        <div>
          <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
            Adresse email <span className="text-red-500">*</span>
          </label>
          <div className="relative">
            <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 text-neutral-400" size={20} />
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              placeholder="vous@exemple.com"
              className={`
                w-full pl-11 pr-4 py-3.5 rounded-lg border
                ${errors.email 
                  ? 'border-red-300 dark:border-red-700 bg-red-50 dark:bg-red-900/20' 
                  : 'border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-800'
                }
                text-neutral-900 dark:text-white
                placeholder-neutral-500 dark:placeholder-neutral-400
                focus:outline-none focus:ring-2 focus:ring-primary-500/50
                transition-all duration-200
              `}
            />
          </div>
          {errors.email && (
            <p className="mt-2 text-sm text-red-600 dark:text-red-400">
              {errors.email}
            </p>
          )}
        </div>

        {/* Password Field */}
        <div>
          <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
            Mot de passe <span className="text-red-500">*</span>
          </label>
          <div className="relative">
            <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 text-neutral-400" size={20} />
            <input
              type={showPassword ? "text" : "password"}
              name="password"
              value={formData.password}
              onChange={handleChange}
              placeholder="Votre mot de passe"
              className={`
                w-full pl-11 pr-12 py-3.5 rounded-lg border
                ${errors.password 
                  ? 'border-red-300 dark:border-red-700 bg-red-50 dark:bg-red-900/20' 
                  : 'border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-800'
                }
                text-neutral-900 dark:text-white
                placeholder-neutral-500 dark:placeholder-neutral-400
                focus:outline-none focus:ring-2 focus:ring-primary-500/50
                transition-all duration-200
              `}
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3 top-1/2 transform -translate-y-1/2 text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300"
            >
              {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
            </button>
          </div>
          {errors.password && (
            <p className="mt-2 text-sm text-red-600 dark:text-red-400">
              {errors.password}
            </p>
          )}
        </div>

        {/* Options */}
        <div className="flex items-center justify-between">
          <label className="flex items-center space-x-3 cursor-pointer">
            <div className="relative">
              <input
                type="checkbox"
                name="rememberMe"
                checked={formData.rememberMe}
                onChange={handleChange}
                className="absolute opacity-0 w-0 h-0"
                id="rememberMe"
              />
              <div className={`
                w-5 h-5 rounded border flex items-center justify-center
                ${formData.rememberMe 
                  ? 'bg-primary-600 border-primary-600' 
                  : 'border-neutral-300 dark:border-neutral-700'
                }
                transition-colors duration-200
              `}>
                {formData.rememberMe && (
                  <div className="w-2 h-2 bg-white rounded-sm"></div>
                )}
              </div>
            </div>
            <span className="text-sm text-neutral-700 dark:text-neutral-300">
              Se souvenir de moi
            </span>
          </label>
        </div>

        {/* Submit button */}
        <button
          type="submit"
          disabled={isSubmitting}
          className={`
            w-full py-3.5 px-4 rounded-lg font-semibold
            ${isSubmitting 
              ? 'bg-primary-400 cursor-not-allowed' 
              : 'bg-primary-600 hover:bg-primary-700'
            }
            text-white
            focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2
            transition-all duration-200
            transform hover:scale-[1.02] active:scale-[0.98]
            shadow-lg hover:shadow-xl
          `}
        >
          {isSubmitting ? (
            <div className="flex items-center justify-center">
              <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white mr-2"></div>
              Connexion en cours...
            </div>
          ) : (
            "Se connecter"
          )}
        </button>
      </form>
    </AuthLayout>
  );
};

export default Login;
